def cmd_serve(args):
    """启动 HTTP/WebSocket 服务器。"""
    from agent_runtime.server.app import run_server
    host = args.host or '127.0.0.1'
    port = args.port or 8900

    # 如果指定了平台连接，设置环境变量
    if args.platform:
        os.environ['PLATFORM_WS_URL'] = args.platform
    if args.agent_id:
        os.environ['AGENT_ID'] = args.agent_id
    if args.mode:
        os.environ['AGENT_RUN_MODE'] = args.mode

    print(f'═══ OpenChiip Agent Framework v0.0.30 ═══')
    print(f'服务器: http://{host}:{port}')
    print(f'Web UI: http://{host}:{port}/')
    print(f'API:    http://{host}:{port}/api/v1/status')
    print(f'WS:     ws://{host}:{port}/ws')
    print()

    run_server(host=host, port=port)
    return 0


