def cmd_chat(args):
    """命令行对话。"""
    from agent_runtime.core.config import RuntimeConfig
    from agent_runtime.core.db import Database
    from agent_runtime.core.llm_client import TokenMeter, LLMClient, AuxiliaryClient
    from agent_runtime.core.memory import MemoryManager

    config = _load_config()
    if not config:
        print('请先运行 `openchiip-harness init` 初始化配置')
        return 1

    db = Database(config.db_file)
    meter = TokenMeter(config.token_meter_file, db=db)
    llm = LLMClient(config, meter)

    if args.interactive:
        print('═══ OpenChiip Agent 交互模式 ═══')
        print('输入 "quit" 或 Ctrl+C 退出\n')
        while True:
            try:
                msg = input('你: ').strip()
                if msg.lower() in ('quit', 'exit', 'q'):
                    break
                if not msg:
                    continue
                reply = llm.chat([
                    {'role': 'system', 'content': '你是 OpenChiip Agent，使用中文回答。'},
                    {'role': 'user', 'content': msg},
                ])
                print(f'Agent: {reply}\n')
            except (KeyboardInterrupt, EOFError):
                break
    else:
        if not args.message:
            print('请提供消息: openchiip-harness chat "你好"')
            return 1
        reply = llm.chat([
            {'role': 'system', 'content': '你是 OpenChiip Agent，使用中文回答。'},
            {'role': 'user', 'content': args.message},
        ])
        print(reply)

    db.close()
    return 0


