def cmd_config(args):
    """配置管理。"""
    import yaml
    config_file = Path.home() / '.openchiip-harness' / 'config.yaml'
    if not config_file.exists():
        print('未初始化配置，请先运行 `openchiip-harness init`')
        return 1

    with open(config_file) as f:
        cfg = yaml.safe_load(f) or {}

    if args.action == 'get':
        keys = args.key.split('.')
        val = cfg
        for k in keys:
            if isinstance(val, dict):
                val = val.get(k)
            else:
                val = None
                break
        print(f'{args.key} = {val}')
    elif args.action == 'set':
        keys = args.key.split('.')
        d = cfg
        for k in keys[:-1]:
            d = d.setdefault(k, {})
        # Try to parse as number/bool
        val = args.value
        try:
            val = int(val)
        except ValueError:
            try:
                val = float(val)
            except ValueError:
                if val.lower() in ('true', 'yes'):
                    val = True
                elif val.lower() in ('false', 'no'):
                    val = False
        d[keys[-1]] = val
        with open(config_file, 'w') as f:
            yaml.dump(cfg, f, default_flow_style=False, allow_unicode=True)
        print(f'✓ {args.key} = {val}')
    return 0


def _load_config():
    """加载配置。"""
    import yaml
    from agent_runtime.core.config import RuntimeConfig

    config_file = Path.home() / '.openchiip-harness' / 'config.yaml'
    if not config_file.exists():
        return None

    with open(config_file) as f:
        cfg = yaml.safe_load(f) or {}

    llm_cfg = cfg.get('llm', {})
    platform_cfg = cfg.get('platform', {})
    storage_cfg = cfg.get('storage', {})

    agent_id = platform_cfg.get('agent_id') or os.environ.get('AGENT_ID', 'standalone')

    # 设置 RuntimeConfig 读取的环境变量
    data_dir = Path(storage_cfg.get('data_dir',
                                    Path.home() / '.openchiip-harness' / 'data'))
    os.environ.setdefault('AGENT_ID', agent_id)
    os.environ.setdefault('AGENT_RUNTIME_HOME', str(data_dir))
    os.environ.setdefault('MODEL_NAME', llm_cfg.get('model_name', 'ernie-5.1'))
    os.environ.setdefault('FAST_MODEL_NAME',
                          llm_cfg.get('fast_model_name', 'ernie-4.5-turbo-128k'))

    api_key = llm_cfg.get('api_key', '')
    if api_key:
        os.environ.setdefault('LLM_API_KEY', api_key)

    provider = llm_cfg.get('provider', 'baidu')
    model_server = llm_cfg.get('model_server', '')
    if not model_server:
        defaults = {
            'baidu': 'https://aip.baidubce.com/rpc/2.0/ai_custom/v1/wenxinworkshop',
            'openai': 'https://api.openai.com/v1',
        }
        model_server = defaults.get(provider, '')
    if model_server:
        os.environ.setdefault('MODEL_SERVER', model_server)

    return RuntimeConfig(agent_id=agent_id)


def main():
    parser = argparse.ArgumentParser(
        description='OpenChiip Agent Framework CLI',
        prog='openchiip-harness',
    )
    parser.add_argument('--version', action='version',
                        version='OpenChiip Agent Framework 0.0.30')

    subparsers = parser.add_subparsers(dest='command')

    # init
    p_init = subparsers.add_parser('init', help='初始化配置')
    p_init.add_argument('--force', action='store_true', help='覆盖已有配置')

    # serve
    p_serve = subparsers.add_parser('serve', help='启动 HTTP/WebSocket 服务器')
    p_serve.add_argument('--host', default='127.0.0.1', help='监听地址')
    p_serve.add_argument('--port', type=int, default=8900, help='监听端口')
    p_serve.add_argument('--platform', help='平台 WS URL（协同模式）')
    p_serve.add_argument('--agent-id', help='Agent ID（协同模式）')
    p_serve.add_argument('--mode', choices=['local', 'collaborative', 'order'],
                         help='运行模式（local=本地, collaborative=协同, order=接单）')

    # run (兼容旧模式)
    p_run = subparsers.add_parser('run', help='兼容旧模式（纯 WS 客户端）')
    p_run.add_argument('agent_id', help='Agent ID')

    # chat
    p_chat = subparsers.add_parser('chat', help='命令行对话')
    p_chat.add_argument('message', nargs='?', help='消息内容')
    p_chat.add_argument('--interactive', '-i', action='store_true',
                        help='交互模式')

    # status
    p_status = subparsers.add_parser('status', help='查看状态')

    # skills
    p_skills = subparsers.add_parser('skills', help='技能管理')
    p_skills.add_argument('action', choices=['list', 'install', 'remove'])
    p_skills.add_argument('source', nargs='?', help='安装源（路径/URL/Git）')
    p_skills.add_argument('skill_id', nargs='?', help='技能 ID（卸载用）')

    # metaskills
    p_ms = subparsers.add_parser('metaskills', help='元技能管理')
    p_ms.add_argument('action', choices=['list', 'run'])
    p_ms.add_argument('name', nargs='?', help='元技能名称')
    p_ms.add_argument('--args', help='参数 JSON')

    # cmd
    p_cmd = subparsers.add_parser('cmd', help='执行控制指令')
    p_cmd.add_argument('command', help='指令（如 /status）')

    # a2a
    p_a2a = subparsers.add_parser('a2a', help='A2A 协作')
    p_a2a.add_argument('action', choices=['card', 'peers', 'invoke'])
    p_a2a.add_argument('agent_id', nargs='?', help='目标 Agent ID')
    p_a2a.add_argument('message', nargs='?', help='消息')

    # tools
    p_tools = subparsers.add_parser('tools', help='工具管理')
    p_tools.add_argument('action', choices=['list'])

    # init-tools（Docker 预装/平台协同：将已存在的 CLI Agent 写入安装记录）
    p_init_tools = subparsers.add_parser(
        'init-tools', help='初始化预装工具记录（扫描已存在的 CLI Agent）')
    p_init_tools.add_argument(
        '--source', default='docker-preinstall',
        help='安装记录来源标记（默认 docker-preinstall）')

    # memory
    p_mem = subparsers.add_parser('memory', help='记忆管理')
    p_mem.add_argument('action', choices=['search', 'clear'])
    p_mem.add_argument('query', nargs='?', help='搜索关键词')

    # config
    p_cfg = subparsers.add_parser('config', help='配置管理')
    p_cfg.add_argument('action', choices=['get', 'set'])
    p_cfg.add_argument('key', help='配置键（如 llm.model_name）')
    p_cfg.add_argument('value', nargs='?', help='配置值（set 时必填）')

    args = parser.parse_args()

    dispatch = {
        'init': cmd_init,
        'serve': cmd_serve,
        'run': cmd_run,
        'chat': cmd_chat,
        'status': cmd_status,
        'skills': cmd_skills,
        'metaskills': cmd_metaskills,
        'cmd': cmd_cmd,
        'a2a': cmd_a2a,
        'tools': cmd_tools,
        'init-tools': cmd_init_tools,
        'memory': cmd_memory,
        'config': cmd_config,
    }

    handler = dispatch.get(args.command)
    if handler:
        return handler(args)
    else:
        parser.print_help()
        return 0


if __name__ == '__main__':
    sys.exit(main() or 0)
